fun safeLength(text: String?): Int? {
    return text?.length
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithString() {
        Assert.assertEquals(7, safeLength("Tribots"))
    }

    @Test
    fun testWithNull() {
        Assert.assertNull(safeLength(null))
    }

    @Test
    fun testWithEmptyString() {
        Assert.assertEquals(0, safeLength(""))
    }

    @Test
    fun testWithTeamNumber() {
        Assert.assertEquals(4, safeLength("4215"))
    }
}
